import { parseHTML } from "linkedom";
//#region src/internal/environments/browser-environment.ts
function getBrowserEnvironmentGlobals() {
	const { window, document, global } = parseHTML(`
    <html>
      <head></head>
      <body></body>
    </html>
  `);
	const location = createBuildTimeLocation("http://localhost/");
	window.location = location;
	global.location = location;
	return {
		...global,
		window,
		document,
		self: global,
		location
	};
}
/**
* A read-only stand-in for `location`. There is no page to navigate at build
* time, so `assign`, `reload` and `replace` do nothing rather than throw.
*/
function createBuildTimeLocation(href) {
	const url = new URL(href);
	return {
		ancestorOrigins: Object.assign([], {
			contains: () => false,
			item: () => null
		}),
		hash: url.hash,
		host: url.host,
		hostname: url.hostname,
		href: url.href,
		origin: url.origin,
		pathname: url.pathname,
		port: url.port,
		protocol: url.protocol,
		search: url.search,
		assign: () => {},
		reload: () => {},
		replace: () => {},
		toString: () => url.href
	};
}
//#endregion
export { getBrowserEnvironmentGlobals };
